  -- Modules
  INSERT INTO public.modules (id, course_id, title, description, content, order_index, duration_minutes, has_quiz, quiz_pass_mark) VALUES
  (v_mod_ids[1], v_course_id, 'Why Batteries Need Special Handling',
   'The scale of the battery problem in Ontario, what is inside a battery, and the critical-minerals opportunity.',
   E'<h2>Batteries Are Everywhere — and That''s a Problem</h2><p>Ontario households own hundreds of batteries at any given time. They power everything from television remotes and smoke detectors to laptops, power tools, e-bikes, electric vehicles, and medical devices. As the world shifts toward electrification and renewable energy, the number and variety of batteries in our lives is growing rapidly.</p><p>This growth creates both a <strong>challenge</strong> and an <strong>opportunity</strong>. The challenge: batteries contain hazardous materials — heavy metals, acids, and reactive lithium compounds — that are dangerous when improperly discarded. The opportunity: those same materials are valuable critical minerals that can be extracted and reused, supporting Ontario''s clean-energy economy.</p><h3>Key Numbers</h3><ul><li><strong>162%</strong> increase in lithium-ion battery fires in Toronto over 2 years (Toronto Fire Services)</li><li><strong>45%</strong> of batteries supplied into Ontario must be recovered under the 2025 RPRA requirement</li><li><strong>20,000+</strong> free battery drop-off locations across Ontario</li><li><strong>$Billions</strong> in critical minerals locked inside batteries — lithium, cobalt, nickel, lead, manganese</li></ul><h3>What''s Inside a Battery — and Why It Matters</h3><ul><li><strong>Lead</strong> — Found in sealed lead-acid batteries (car batteries, emergency lighting). A toxic heavy metal that accumulates in soil, water, and human tissue. There is no safe level of lead exposure.</li><li><strong>Cadmium</strong> — Older nickel-cadmium rechargeables. A carcinogen that persists in the environment for decades and harms kidney function.</li><li><strong>Mercury</strong> — Some button cells (silver-oxide, zinc-air). Mercury vapour is toxic and bioaccumulates through waterways.</li><li><strong>Lithium</strong> — All lithium-ion and lithium-metal batteries. Reacts violently with water, causes severe burns, highly flammable. Damaged lithium batteries can ignite spontaneously.</li><li><strong>Cobalt & Nickel</strong> — Key components of lithium-ion batteries. Mining causes significant environmental damage and human-rights concerns in source countries.</li><li><strong>Sulfuric acid</strong> — The electrolyte in lead-acid batteries. Causes severe chemical burns and permanently damages soil and waterways on release.</li><li><strong>Potassium hydroxide</strong> — Electrolyte in alkaline batteries. Caustic and corrosive — causes burns and damages infrastructure when leaking batteries are left in devices.</li></ul><h3>The Scale of the Problem in Ontario</h3><p>Despite widespread awareness campaigns, batteries remain one of the most commonly misplaced items in Ontario''s waste stream. They are found in blue bins, green bins, and garbage bags — where they cause damage ranging from contaminated recycling loads to catastrophic fires.</p><p>Toronto Fire Services reported a <strong>38% year-over-year increase</strong> in lithium-ion battery fires in 2024 compared to 2023 — and a <strong>162% increase</strong> over two years. Across Canada, battery-related fires have destroyed garbage trucks, injured waste collection workers, and caused multi-million-dollar damage at Material Recovery Facilities.</p><p>The Ontario Fire Marshal''s <strong>Charged for LiFE</strong> campaign identifies battery disposal as one of the fastest-growing fire-safety challenges facing Ontario communities.</p><h3>Real-World Example — A Mississauga Apartment Chute Fire</h3><p>A Mississauga apartment building''s garbage chute caught fire when a tenant discarded an e-cigarette containing a lithium-ion battery. The fire required multiple fire trucks and caused significant damage. The fire was entirely preventable — e-cigarettes must always be taken to electronics or battery drop-off locations, never discarded in any bin.</p><h3>The Opportunity — Critical Minerals Recovery</h3><p>Every battery that is correctly collected and processed is a source of critical minerals that Ontario and Canada need for the clean-energy transition. Lithium-ion batteries contain lithium, cobalt, nickel, and manganese — materials currently mined with significant environmental impact in countries including the Democratic Republic of Congo, Chile, and Australia.</p><p>Battery recycling recovers these minerals and returns them to the manufacturing supply chain. A fully recovered lithium-ion battery can provide materials for new battery cells, reducing the demand for new mining by an equivalent amount.</p><h3>Key Message</h3><p>Batteries are <strong>NOT garbage</strong> — they are classified as <strong>Household Hazardous Waste</strong> under Ontario regulations. They must never go in any regular bin. They must always go to a designated drop-off location — and there are over 20,000 of them across Ontario, all free to use.</p>',
   1, 10, true, 70),

  (v_mod_ids[2], v_course_id, 'Know Your Battery Types',
   'The eight major battery types in Ontario — chemistry, common uses, recycling path, and fire risk.',
   E'<h2>Not All Batteries Are the Same</h2><p>Ontario''s Batteries Regulation covers batteries sold separately that weigh <strong>5 kg or less</strong>. Understanding the differences between battery types is essential — each type contains different chemicals, presents different hazard profiles, and requires different handling precautions.</p><p>The most important distinction is between <strong>single-use (primary) batteries</strong> and <strong>rechargeable (secondary) batteries</strong> — and within rechargeable, between older chemistry types and modern lithium-ion batteries that power most of today''s electronics and transportation.</p><h3>The Eight Major Battery Types</h3><ul><li><strong>Alkaline (AA, AAA, C, D, 9V)</strong> — Zinc-manganese dioxide. Remotes, toys, clocks, flashlights, smoke detectors. Drop off at any RPRA location. Fire risk: LOW.</li><li><strong>Button / Coin Cells</strong> — Silver oxide, zinc-air, lithium. Watches, hearing aids, key fobs, medical devices. Tape terminals before drop-off. Fire risk: MEDIUM (lithium types).</li><li><strong>Nickel-Cadmium (NiCd)</strong> — Older power tools, cordless phones, cameras. Contains cadmium — handle with care. Fire risk: LOW–MEDIUM.</li><li><strong>Nickel-Metal Hydride (NiMH)</strong> — AA/AAA rechargeables, hybrid vehicle packs. Fire risk: LOW–MEDIUM.</li><li><strong>Lithium-Ion (Li-ion)</strong> — Phones, laptops, tablets, EVs, e-bikes, power tools. REMOVE from device first; tape terminals. Fire risk: <strong>HIGH</strong>.</li><li><strong>Lithium Primary (non-rechargeable)</strong> — 10-year smoke alarms, medical devices, cameras. Never puncture or crush. Fire risk: <strong>HIGH</strong>.</li><li><strong>Sealed Lead-Acid (SLA)</strong> — Emergency lighting, UPS systems, mobility devices. Free at auto-parts stores and battery retailers. Fire risk: MEDIUM.</li><li><strong>Lead-Acid (large)</strong> — Car, truck, motorcycle batteries. Not in the RPRA program — take to Canadian Tire, Napa, or Mr. Lube (free). Fire risk: HIGH if damaged.</li></ul><h3>Single-Use vs. Rechargeable — Key Differences</h3><ul><li><strong>Single-use (Primary)</strong> — Designed for one use only. Alkaline, carbon-zinc, lithium primary, silver-oxide button cells. Once depleted, must be recycled — never refilled or recharged (leaking, swelling, or rupture risk).</li><li><strong>Rechargeable (Secondary)</strong> — Designed for hundreds to thousands of charge cycles. NiCd, NiMH, Li-ion, lithium polymer. A battery that no longer holds charge should be recycled, not discarded.</li></ul><h3>What the RPRA Program Covers</h3><p>The Ontario Batteries Regulation covers all single-use AND all rechargeable batteries weighing <strong>5 kg or less</strong> when sold separately from the device they power. Batteries sold with or inside a device (a phone sold with its battery) are not covered by the Battery Regulation — but they are still covered by Ontario''s free electronics drop-off programs.</p><h3>The Button Battery Danger — A Critical Warning for Families</h3><p>Button batteries (coin cells) are a <strong>leading cause of serious injury and death in young children</strong>. A button battery swallowed by a child can cause severe internal chemical burns <strong>within 2 hours</strong> of ingestion. This is a medical emergency — call <strong>911 immediately</strong>.</p><p>Keep all button batteries out of reach of children. Store in sealed containers. Dispose of immediately when depleted — do not leave dead button batteries lying around. Check existing devices at home and ensure battery covers are secured.</p><h3>Recognising a Battery in Trouble</h3><p>Any battery showing the following signs should be handled carefully and taken to a drop-off location as a priority:</p><ul><li>Swelling, puffiness, or visible deformation of the casing</li><li>Leakage, residue, or corrosion</li><li>Heat when not charging or in use</li><li>Unusual chemical smell</li><li>Hissing, crackling, or popping sounds</li></ul><p>Do <strong>NOT</strong> attempt to charge, use, or disassemble a damaged battery. Place in a non-flammable container (sand or cat litter) for transport. Never put a damaged battery in any regular bin — it is a fire hazard.</p><h3>Did You Know — Thermal Runaway</h3><p><strong>Thermal runaway</strong> is the self-reinforcing chain reaction inside a failing lithium-ion battery. Once triggered by damage, overcharging, or a manufacturing defect, internal heat generation accelerates — temperatures can reach <strong>537°C (1,000°F)</strong>, releasing flammable and toxic gases and potentially causing an explosive fire that is extremely difficult to extinguish.</p>',
   2, 12, true, 70),

  (v_mod_ids[3], v_course_id, 'Ontario''s Battery Regulation & RPRA',
   'The legal framework, producer obligations, and what consumers need to know about Ontario''s Batteries Regulation.',
   E'<h2>The Legal Framework — What the Law Says</h2><p>Battery recycling in Ontario is governed by the <strong>Batteries Regulation</strong>, enacted under the <strong>Resource Recovery and Circular Economy Act, 2016 (RRCEA)</strong>. This legislation established Ontario''s <strong>Extended Producer Responsibility (EPR)</strong> framework — a system that makes producers (manufacturers and importers) financially and legally responsible for collecting and recycling the batteries they sell into Ontario.</p><p>The Batteries Regulation took effect <strong>July 1, 2020</strong>. From that date, battery producers became individually accountable for collecting and reusing, refurbishing, or recycling batteries when consumers discard them. The program is enforced by the <strong>Resource Productivity and Recovery Authority (RPRA)</strong> — Ontario''s independent regulatory body for recycling programs.</p><h3>About RPRA</h3><p>RPRA enforces six Ontario recycling programs: <strong>Blue Box, Batteries, Electronics, Household Hazardous Waste, Lighting, and Tires</strong>. Under EPR, RPRA sets mandatory recovery targets, registers producers and service providers, monitors compliance, and can issue compliance orders and administrative penalties to producers who fail to meet their obligations. Visit <strong>rpra.ca</strong> for all program information.</p><h3>What Is Covered Under the Batteries Regulation</h3><ul><li><strong>✓ Covered</strong> — Single-use batteries ≤5 kg sold separately (button cells, AA, AAA, C, D, 9V, lantern batteries)</li><li><strong>✓ Covered</strong> — Rechargeable batteries ≤5 kg sold separately (sealed lead-acid, NiCd, NiMH, Li-ion, laptop/phone replacement batteries)</li><li><strong>✗ Not Covered</strong> — Batteries sold inside products (use free electronics drop-off instead)</li><li><strong>✗ Not Covered</strong> — Batteries over 5 kg, car batteries, forklift batteries (use auto retailers or HHW depots)</li><li><strong>✗ Not Covered</strong> — EV battery packs and large e-bike batteries (manufacturer take-back)</li></ul><h3>Who Is a "Producer"?</h3><p>A business is a battery <strong>producer</strong> — and therefore has obligations under the Batteries Regulation — if they supply batteries into Ontario AND one of the following applies:</p><ul><li>They are the brand holder of the battery AND have residency in Canada</li><li>They have residency in Ontario AND import batteries from outside Ontario</li><li>They have residency in Ontario AND market batteries directly to consumers (e.g., online sales)</li><li>They do NOT have residency in Ontario but market directly to Ontario consumers</li></ul><p>If you operate an Ontario business that imports batteries under your own brand, sells batteries online to Ontario customers, or is the first-in-market seller of a battery product, you may be a <strong>registered producer</strong>. Check rpra.ca or contact RPRA at <strong>1-833-600-0530</strong>.</p><h3>The 45% Recovery Requirement</h3><p>For the 2025 performance period, every obligated battery producer must ensure that <strong>at least 45%</strong> of the batteries they supplied into Ontario are reused, refurbished, or recycled. Annual reporting is due <strong>April 30</strong>.</p><p>Producers meet their obligations by either:</p><ul><li>Establishing and operating their own battery collection and management systems, OR</li><li>Working with a <strong>Producer Responsibility Organization (PRO)</strong> that runs collection networks on their behalf</li></ul><p>Registered PROs operating in Ontario include <strong>Call2Recycle</strong> (call2recycle.ca) and the <strong>Canadian Battery Association</strong> (canadianbatteryassociation.ca).</p><h3>What Consumers Need to Know</h3><ul><li><strong>Is there a cost to drop off?</strong> No. Battery drop-off at RPRA-registered locations is always free for consumers.</li><li><strong>Do I need to register or report?</strong> No. Individual consumers have no registration or reporting obligations.</li><li><strong>Where do I find a drop-off location?</strong> Visit <strong>rpra.ca/where-to-recycle</strong> — over 20,000 locations province-wide.</li><li><strong>Large quantities?</strong> Organizations, First Nations, and municipalities should contact a PRO directly once they have collected one tonne.</li><li><strong>Devices with batteries?</strong> Take whole devices (phones, laptops, tablets) to an electronics drop-off — the battery is handled with the device.</li><li><strong>Car batteries?</strong> Not in RPRA scope — auto-parts retailers (Canadian Tire, Napa, Mr. Lube) accept them free.</li></ul><h3>Environmental Fees — The Facts</h3><p>You may notice an "environmental fee" or "battery recycling fee" on your receipt. Important facts:</p><ul><li>Environmental fees are <strong>NOT government taxes</strong> and cannot legally be presented as such</li><li>RPRA does <strong>NOT set, require, or endorse</strong> any environmental fee at point of sale</li><li>Businesses choose <strong>whether</strong> to charge this fee and set the amount at their own discretion</li><li>The fee goes to the retailer and may or may not be passed to a PRO or producer</li></ul><p>If misrepresented as a tax, contact the Ministry of Public and Business Service Delivery: <strong>1-800-889-9768</strong>.</p>',
   3, 12, true, 70),

  (v_mod_ids[4], v_course_id, 'Fire Safety — Lithium-Ion Batteries',
   'Thermal runaway, safe purchasing, charging, storage, and emergency response for lithium-ion batteries.',
   E'<h2>The Scale of the Fire Risk</h2><p>This module contains critical fire-safety information from the <strong>Ontario Fire Marshal</strong>, <strong>Toronto Fire Services</strong>, and <strong>Health Canada</strong>. The incidents described are real events occurring across Ontario. Lithium-ion battery fires are fast-growing, toxic, and extremely difficult to extinguish.</p><p>Lithium-ion batteries power nearly every rechargeable device in modern life — phones, laptops, tablets, electric toothbrushes, power tools, e-bikes, e-scooters, mobility scooters, and electric vehicles. As these devices proliferate, so does the risk from batteries charged incorrectly, stored unsafely, damaged, or improperly discarded.</p><p>Toronto Fire Services reported <strong>55 lithium-ion battery fires in 2023</strong>, rising <strong>38% in 2024</strong> — a <strong>162% increase over two years</strong>. Four garbage trucks in Halifax caught fire in a single year due to batteries in the trash. Across Ontario, Material Recovery Facilities have experienced multiple fires per year from batteries crushed in sorting machinery.</p><p>The <strong>Charged for LiFE</strong> campaign identifies four key safety areas: safe purchasing, correct charging, no tampering, and proper disposal.</p><h3>Understanding Thermal Runaway</h3><p>Thermal runaway is the <strong>self-reinforcing chain reaction</strong> triggered by heat, damage, or electrical failure inside a battery cell.</p><ul><li><strong>What causes it</strong> — Physical damage (crushing, puncture, bending), overcharging, overheating, internal manufacturing defect, short circuit, or immersion in water.</li><li><strong>What happens</strong> — The battery self-heats. Heat accelerates chemical breakdown. This produces more heat. Temperature can reach <strong>537°C (1,000°F)</strong>. Flammable and toxic gases are released — hydrogen fluoride, carbon monoxide, methane.</li><li><strong>What the fire looks like</strong> — Lithium fires burn extremely hot and fast. They may appear extinguished and reignite minutes or hours later. <strong>Water CANNOT safely extinguish them</strong> — water reacts with lithium to produce hydrogen gas, potentially worsening the fire or causing an explosion.</li><li><strong>Signs a battery is failing</strong> — Battery warm or hot when idle, swollen or puffy casing, unexpected shutdown, unusual sweet/chemical/acrid odour, hissing or crackling sounds.</li></ul><h3>Safe Purchasing — Start Right</h3><p>Many lithium-ion fires in Ontario originate from <strong>counterfeit or uncertified batteries</strong> purchased from online marketplaces without certification, dollar stores, or unbranded imports. These often fail to meet Canadian electrical safety standards.</p><ul><li>✓ Buy batteries and chargers from reputable retailers with certified products</li><li>✓ Look for <strong>CSA or UL certification marks</strong></li><li>✓ Use the charger and cable that came with your device</li><li>✓ Contact original manufacturers for e-bike and power tool replacement chargers</li><li>✗ Never use generic chargers from unknown sellers without certification</li><li>✗ Never mix batteries from different manufacturers in multi-cell devices</li><li>✗ Never modify, open, or repair a battery yourself</li></ul><h3>Safe Charging — The Most Critical Safety Practice</h3><p>Most lithium-ion battery fires occur <strong>during or immediately after charging</strong>. The charging process generates heat and creates electrical conditions that can trigger thermal runaway.</p><ul><li>Always use the <strong>original charger and cable</strong> that came with your device</li><li><strong>Never leave devices charging unattended</strong> — especially overnight or when leaving home</li><li>Charge on a <strong>hard, flat surface</strong> (desk, table, floor) — never on beds, sofas, or carpets that trap heat</li><li><strong>Do not charge in rooms where people sleep</strong> — especially e-bikes, e-scooters, and power tool battery packs</li><li><strong>Unplug devices when fully charged</strong> — overcharging generates excess heat</li><li><strong>Never charge in exit corridors, stairwells, or near exits</strong> — a battery fire there can block evacuation routes</li><li>Charge e-bikes and e-scooters in <strong>well-ventilated spaces</strong> away from exits — ideally outdoors or in a garage</li></ul><h3>Safe Storage</h3><ul><li>Store batteries and devices in a <strong>cool, dry place</strong> — heat accelerates chemical degradation</li><li>Do not store in direct sunlight or hot vehicles — interiors can exceed 60°C</li><li>Store unused lithium-ion batteries at approximately <strong>50% charge</strong></li><li>Check stored batteries every 3 months — top up if significantly discharged</li><li>Keep batteries in a <strong>non-conductive case</strong> — never let terminals contact keys, coins, or other metal</li><li>Separate different battery types — don''t mix alkaline, NiMH, and lithium in one drawer</li></ul><h3>If a Battery Is on Fire or Producing Smoke</h3><p>If a lithium-ion battery is actively on fire, producing smoke, or you smell a burning chemical odour:</p><ol><li><strong>Do not touch</strong> the battery or device with bare hands</li><li>If safe, move the device away from flammable materials</li><li><strong>Evacuate</strong> the room</li><li><strong>Call 911 immediately</strong></li><li><strong>Do NOT use water</strong> — use a Class D fire extinguisher or large quantities of sand/earth to smother (if trained)</li><li><strong>Ventilate the area</strong> — the gases produced are toxic</li></ol><h3>Safe Disposal — The Final Step</h3><ul><li>✓ Remove the battery from the device before disposal (where physically possible)</li><li>✓ <strong>Tape over the terminals</strong> with electrical or clear packing tape</li><li>✓ Place damaged batteries in a sealed, non-flammable container for transport</li><li>✓ Take to an RPRA drop-off: Canadian Tire, Home Depot, Best Buy, municipal depot</li><li>✓ Drop off whole devices with embedded batteries at electronics collection</li><li>✗ Never put batteries in the blue, green, or grey bin — ever</li><li>✗ Never bag batteries thinking "the bag will keep them safe" — it won''t</li><li>✗ Never leave dead batteries in devices — leakage and corrosion follow</li><li>✗ Never attempt to remove batteries from sealed devices yourself</li></ul>',
   4, 12, true, 70),

  (v_mod_ids[5], v_course_id, 'Recycling Your Batteries — How, Where & What Happens Next',
   'How to prepare batteries for drop-off, where to take them, and what happens after collection.',
   E'<h2>How to Prepare Batteries for Drop-Off</h2><p>Correct preparation takes <strong>less than a minute per battery</strong> and protects you, transport workers, and collection-site staff.</p><h3>Step 1: Remove the Battery From the Device</h3><p>Before dropping off any rechargeable battery, remove it from the device if physically possible. For phones, tablets, and laptops with sealed batteries, take the entire device to an <strong>electronics drop-off</strong> — do not force the battery out, as this can damage it.</p><h3>Step 2: Check the Battery''s Condition</h3><p>Inspect for damage: swelling, leakage, cracks, burns, or unusual heat. Damaged batteries are a priority — inform collection-site staff so they can handle them appropriately.</p><h3>Step 3: Tape the Terminals — The Single Most Important Step</h3><p>Use electrical, clear packing, or duct tape to cover the terminals at both ends of the battery. Exposed terminals that touch metal or other battery terminals during transport can cause a short circuit — and a fire.</p><ul><li><strong>AA, AAA, C, D</strong> — tape over both positive (+) and negative (-) ends</li><li><strong>9V</strong> — the two terminals are close together; tape over both simultaneously</li><li><strong>Button cells</strong> — place in a small sealed plastic bag or cover with tape on both sides</li><li><strong>Lithium-ion packs (phone, laptop)</strong> — tape over the entire connector area</li></ul><h3>Step 4: Store Until Drop-Off</h3><p>Collect taped batteries in a <strong>non-metal</strong> container (plastic tub, cardboard box, zip-lock bag) until you have enough to make a drop-off trip worthwhile. Do not stockpile large quantities long-term — drop off regularly to reduce home-storage risk.</p><h3>Step 5: Take to Your Nearest Drop-Off</h3><p>Drop-off is <strong>free</strong>, requires no appointment, and takes under a minute.</p><h2>Where to Drop Off — All Free</h2><h3>Major Retailers (Ontario-wide)</h3><ul><li><strong>Canadian Tire</strong> — Alkaline, rechargeable, button cells, sealed lead-acid. In-store bins at the entrance.</li><li><strong>Home Depot</strong> — All battery types including rechargeable packs. Customer service or entrance.</li><li><strong>Best Buy</strong> — All battery types including phone/laptop batteries.</li><li><strong>IKEA</strong> — Alkaline, rechargeable, button cells.</li><li><strong>Staples</strong> — Alkaline and rechargeable batteries.</li></ul><h3>Municipal & Community</h3><ul><li><strong>Municipal Depots</strong> — All battery types; may include car batteries. Check your local municipality for hours.</li><li><strong>Community Environment Days</strong> — All battery types, including damaged batteries. Check your municipality''s schedule.</li><li><strong>Call2Recycle Locations</strong> — call2recycle.ca lists 9,000+ Canada-wide sites.</li><li><strong>Electronics Retailers</strong> — Whole devices with embedded batteries (phone, laptop, tablet, e-waste).</li></ul><h3>Outside RPRA Scope</h3><ul><li><strong>Car batteries (>5 kg lead-acid)</strong> — Canadian Tire, Napa, Mr. Lube — free.</li></ul><p><strong>Find any drop-off location:</strong> <strong>rpra.ca/where-to-recycle</strong> — 20,000+ free Ontario locations, filterable by battery type.</p><h2>Setting Up a Battery Collection Point</h2><p>A dedicated, clearly labelled collection point is the most effective way to ensure batteries get recycled correctly.</p><h3>At Home</h3><ul><li>Use a small plastic container, tin, or jar with a lid — label "DEAD BATTERIES — For Recycling"</li><li>Place it visible and accessible: junk drawer, kitchen counter, utility room</li><li>Keep away from heat sources, sunlight, and children</li><li>Empty when full to your nearest RPRA drop-off</li></ul><h3>In an Apartment or Condominium</h3><ul><li>Propose a building-wide program to your property manager or condo board</li><li>A locked collection box in the mailroom, laundry room, or waste area</li><li>Contact <strong>Call2Recycle</strong> for free collection-box programs for multi-unit residential buildings</li><li>Post multilingual signage explaining what goes in and where it goes</li></ul><h3>In a School or Community Organization</h3><ul><li>Run battery collection drives as an environmental-education activity</li><li>A single labelled bin in the office or common area is enough</li><li>Contact Call2Recycle for free containers and program support</li></ul><h3>In a Business or SME</h3><ul><li>Place labelled boxes at reception, server rooms, copy stations, and anywhere battery-powered equipment is used</li><li>Include battery disposal in onboarding and annual safety training</li><li>Designate a <strong>battery champion</strong> who ensures full boxes go to drop-off</li></ul><h2>What Happens After Collection?</h2><ol><li><strong>Collection</strong> — Drop-off sites are emptied by licensed haulers registered with RPRA, who transport to registered processors.</li><li><strong>Sorting by Type</strong> — Processors sort by chemistry — each type needs different processing and produces different recovered materials.</li><li><strong>Alkaline Processing</strong> — Shredded; steel, zinc, and manganese are separated and sold to manufacturers of new batteries, fertilizers, and industrial compounds.</li><li><strong>Lead-Acid Processing</strong> — One of the most efficiently recycled products in the world. Lead is smelted for new battery production, plastic casings are reprocessed, electrolyte is neutralised or reclaimed.</li><li><strong>Lithium-Ion Processing</strong> — Discharged, disassembled, and shredded under controlled conditions. <strong>Black mass</strong> — a mixture of lithium, cobalt, nickel, and manganese — is extracted and sold to refineries for new battery cells.</li><li><strong>Resource Recovery</strong> — Recovered materials re-enter the supply chain: lithium and cobalt to new batteries, steel to new products, plastics reused.</li><li><strong>RPRA Reporting</strong> — Processors report recovered weights annually to RPRA, which uses the data to verify that producers met their <strong>45% recovery requirement</strong>.</li></ol><h3>Did You Know</h3><p>Canada is investing heavily in battery recycling infrastructure as part of its <strong>Critical Minerals Strategy</strong> and clean-energy transition. Ontario is home to several battery recycling facilities and is positioned to become a major hub as EV adoption accelerates. The batteries you recycle today become the clean-energy economy of tomorrow.</p>',
   5, 12, true, 70),

  (v_mod_ids[6], v_course_id, 'Final Quiz — Battery Recycling in Ontario',
   'A 10-question final assessment covering all five modules. Pass mark 70%.',
   E'<h2>Final Knowledge Check</h2><p>This 10-question quiz covers everything you''ve learned across the five modules of Battery Recycling in Ontario. A passing score (70%) demonstrates your readiness to handle, store, and recycle batteries safely.</p><p>Questions are drawn from across the course — battery types and chemistry, Ontario''s Batteries Regulation, lithium-ion fire safety, and correct recycling procedures.</p><p>Good luck!</p>',
   6, 10, true, 70);

  -- Quiz Questions
  -- Module 1
  INSERT INTO public.quiz_questions (module_id, question, options, correct_answer_index, order_index) VALUES
  (v_mod_ids[1], 'A family finds several used batteries in a junk drawer. What is the correct action?', '["Put them in the blue recycling bin","Bag them and put in the garbage","Tape the terminals and take to a free RPRA-designated drop-off location","Bury them in the garden"]'::jsonb, 2, 1),
  (v_mod_ids[1], 'Toronto Fire Services reported what percentage increase in lithium-ion battery fires over a two-year period?', '["15%","38%","162%","400%"]'::jsonb, 2, 2),
  (v_mod_ids[1], 'What is the value of correctly recycling batteries beyond avoiding landfill contamination?', '["There is no additional value — recycling is purely a regulatory requirement","Batteries recover critical minerals — lithium, cobalt, nickel — needed for clean energy manufacturing","Recycled batteries are refurbished and resold as used products","Recycling batteries generates electricity for local communities"]'::jsonb, 1, 3);

  -- Module 2
  INSERT INTO public.quiz_questions (module_id, question, options, correct_answer_index, order_index) VALUES
  (v_mod_ids[2], 'A child swallows a small round battery from a toy remote control. What is the immediate action?', '["Give the child a glass of milk and monitor for 24 hours","Call Poison Control and wait for a callback","Call 911 immediately — button battery ingestion is a medical emergency that can cause severe internal burns within 2 hours","The battery will pass safely — it is too small to cause harm"]'::jsonb, 2, 1),
  (v_mod_ids[2], 'A laptop battery appears swollen and the laptop casing is slightly deformed. What should the user do?', '["Keep using the laptop — swelling is normal as batteries age","Charge the laptop fully to see if the swelling resolves","Stop using the device, isolate the laptop, and take it to a drop-off location as a priority","Remove the battery and place it in the recycling bin"]'::jsonb, 2, 2),
  (v_mod_ids[2], 'Which of the following battery types is covered by Ontario''s RPRA Batteries Regulation?', '["A car battery (lead-acid, 20 kg)","A laptop with its battery sealed inside (sold as one unit)","A replacement phone battery (Li-ion, 60g) sold separately","An EV vehicle battery pack (400 kg)"]'::jsonb, 2, 3);

  -- Module 3
  INSERT INTO public.quiz_questions (module_id, question, options, correct_answer_index, order_index) VALUES
  (v_mod_ids[3], 'When did Ontario''s Batteries Regulation under the RRCEA come into effect?', '["January 1, 2018","July 1, 2020","January 1, 2023","January 1, 2026"]'::jsonb, 1, 1),
  (v_mod_ids[3], 'What is the minimum battery recovery requirement for Ontario producers under the 2025 performance period?', '["25%","45%","70%","100%"]'::jsonb, 1, 2),
  (v_mod_ids[3], 'A consumer sees an "environmental handling fee" on their receipt when buying AA batteries. This fee is:', '["A government-mandated tax collected for RPRA","Set by RPRA to fund the battery collection program","A discretionary business charge — not a government tax, not set by RPRA, not mandatory","A legal requirement under the Batteries Regulation"]'::jsonb, 2, 3);

  -- Module 4
  INSERT INTO public.quiz_questions (module_id, question, options, correct_answer_index, order_index) VALUES
  (v_mod_ids[4], 'A phone battery catches fire while charging on a bedside table. What is the correct first action?', '["Pour water on it immediately to cool it down","Throw a wet towel over it to smother the flame","Evacuate the room, call 911, do not use water — lithium fires produce toxic gases and water can worsen the reaction","Unplug the charger and place the phone in the freezer to cool"]'::jsonb, 2, 1),
  (v_mod_ids[4], 'Which of the following charging practices is SAFE for lithium-ion batteries?', '["Charging a phone under a pillow overnight","Charging an e-bike battery in an apartment hallway","Charging a laptop on a hard desk surface and unplugging when fully charged","Using a generic charger from a dollar store"]'::jsonb, 2, 2),
  (v_mod_ids[4], 'What temperature can a lithium-ion battery reach during thermal runaway?', '["80°C","200°C","537°C (1,000°F)","100°C"]'::jsonb, 2, 3);

  -- Module 5
  INSERT INTO public.quiz_questions (module_id, question, options, correct_answer_index, order_index) VALUES
  (v_mod_ids[5], 'Before taking a 9V alkaline battery to a drop-off location, the correct preparation is to:', '["Discharge it completely by short-circuiting the terminals","Tape over both terminals with electrical tape to prevent short circuits","Place it in a metal container for safety","No preparation is needed — alkaline batteries are safe to transport as-is"]'::jsonb, 1, 1),
  (v_mod_ids[5], 'A building manager wants to set up a battery collection program in a 200-unit condo. The best first step is to:', '["Purchase a large industrial battery storage container","Contact Call2Recycle for free collection box programs designed for multi-unit residential buildings","Ask residents to keep batteries until a municipal collection day","Install a blue bin specifically for batteries"]'::jsonb, 1, 2),
  (v_mod_ids[5], 'During lithium-ion battery recycling, what is "black mass"?', '["The residual ash left after burning batteries for energy recovery","A mixture of lithium, cobalt, nickel, and manganese extracted from shredded Li-ion batteries, sold to refineries for new battery material production","The contaminated plastic casing removed from alkaline batteries","A by-product of lead-acid processing that must be disposed of as hazardous waste"]'::jsonb, 1, 3);

  -- Final Quiz (Module 6) — 10 questions
  INSERT INTO public.quiz_questions (module_id, question, options, correct_answer_index, order_index) VALUES
  (v_mod_ids[6], 'Which of the following battery types carries the HIGHEST fire risk when damaged or improperly handled?', '["Standard alkaline (AA/AAA)","Nickel-metal hydride (NiMH) rechargeable","Lithium-ion (Li-ion) — used in phones, laptops, e-bikes","Carbon-zinc single-use"]'::jsonb, 2, 1),
  (v_mod_ids[6], 'Under Ontario''s Batteries Regulation, who is primarily responsible for funding battery collection and recycling?', '["Ontario taxpayers","Municipal governments","Battery producers — manufacturers and importers — under Extended Producer Responsibility","Waste management companies"]'::jsonb, 2, 2),
  (v_mod_ids[6], 'A resident finds a swollen laptop battery. The correct action is to:', '["Charge it fully — swelling resolves when the battery reaches 100%","Cut open the battery to release the gas","Stop using it immediately, place in a non-metal container, take to an electronics drop-off as a priority","Put it in the garbage — too dangerous to transport"]'::jsonb, 2, 3),
  (v_mod_ids[6], 'What is the minimum battery recovery rate required of Ontario producers for the 2025 performance period?', '["25%","45%","60%","80%"]'::jsonb, 1, 4),
  (v_mod_ids[6], 'A child swallows a coin-sized button battery. What is the immediate correct action?', '["Induce vomiting","Give the child water or milk and monitor","Call 911 immediately — this is a medical emergency","Wait 24 hours and observe"]'::jsonb, 2, 5),
  (v_mod_ids[6], 'Which of the following is the ONLY safe place to dispose of batteries in Ontario?', '["The blue recycling bin","The grey/black garbage bin","A designated RPRA battery drop-off location (Canadian Tire, Home Depot, Best Buy, municipal depot)","The green organics bin"]'::jsonb, 2, 6),
  (v_mod_ids[6], 'Why should lithium-ion batteries never be charged on soft surfaces such as beds or sofas?', '["Soft surfaces cause electrical interference","Soft surfaces trap heat around the device, increasing the risk of thermal runaway and fire","It''s only a risk for older batteries","Soft surfaces discharge the battery faster"]'::jsonb, 1, 7),
  (v_mod_ids[6], 'An Ontario grocery chain imports a house-brand alkaline battery from China and sells it across its Ontario locations. Under the Batteries Regulation, this chain is most likely:', '["Exempt — grocery stores are retail, not producers","A registered producer with recovery and reporting obligations under RPRA","Covered by the Chinese manufacturer''s Canadian registration","Required to pay a provincial eco-tax only"]'::jsonb, 1, 8),
  (v_mod_ids[6], 'During lithium-ion battery recycling, "black mass" is:', '["Hazardous waste that must be landfilled","Battery casing material used for new plastic products","A mixture of critical minerals — lithium, cobalt, nickel, manganese — extracted for new battery manufacturing","Burned to generate energy in waste-to-energy plants"]'::jsonb, 2, 9),
  (v_mod_ids[6], 'What should a person do before dropping off alkaline batteries at a Canadian Tire collection bin?', '["Discharge them completely by shorting the terminals","Tape over the terminals with electrical tape to prevent short circuits","Place them in water to neutralise any acid inside","No preparation is needed for alkaline batteries"]'::jsonb, 1, 10);

END $$;
